file.content:
.choice-btn:hover{ border-color:rgba(255,210,122,.8); box-shadow:0 0 22px rgba(255,210,122,.18);}
.choice-btn:active{ transform:scale(.97); }
.choice-btn:focus-visible{ outline:none; border-color:#fff; box-shadow:0 0 0 2px rgba(255,255,255,.5), 0 0 22px rgba(255,210,122,.3);}
#btn-answer{ border-color:rgba(255,210,122,.45); }
#btn-silent{ border-color:rgba(87,230,201,.35); }

#replay-ctl{
  position:absolute; right:18px; top:18px; z-index:9;
  width:34px; height:34px; border-radius:50%; border:1px solid rgba(234,242,255,.25);
  background:rgba(10,14,22,.4); color:var(--ink-dim); cursor:pointer;
  display:flex; align-items:center; justify-content:center; font-size:15px;
  opacity:.45; transition:opacity .3s ease, border-color .3s ease;
}
#replay-ctl:hover, #replay-ctl:focus-visible{ opacity:1; border-color:rgba(255,210,122,.6); outline:none;}

#replay-hint{
  position:absolute; left:50%; bottom:3.4%; transform:translateX(-50%);
  z-index:8; font-size:11px; letter-spacing:.24em; text-transform:uppercase;
  color:var(--ink-dim); opacity:0; transition:opacity 1.4s ease; text-align:center; pointer-events:none;
}

.sr-only{
  position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden;
  clip:rect(0,0,0,0); white-space:nowrap; border:0;
}

@media (max-width:560px){
  #controls-act2{ gap:14px; bottom:9%; }

