1010	   DOM overlay sync (text, opacity, control visibility) — pure fn of state
1011	--------------------------------------------------------------------- */
1012	function syncDOM(){
1013	  // titlecard
1014	  var tcOp = clamp(1 - Math.abs(state.act===1 ? (state.actTime-2600)/2600 : 2), 0, 1);
1015	  if(state.act === 1 && state.actTime < 5200){
1016	    elTitlecard.style.opacity = String(clamp(state.actTime<1300 ? state.actTime/1300 : (5200-state.actTime)/1600,0,1));
1017	  } else {
1018	    elTitlecard.style.opacity = "0";
1019	  }
1020	
1021	  if(state.act === 1){
1022	    var clockOp = clamp((state.actTime-CLOCK_FADE_START)/CLOCK_FADE_MS,0,1) - (state.actTime>ACT1_FADEOUT_START?clamp((state.actTime-ACT1_FADEOUT_START)/1200,0,1):0);
1023	    elClock.style.opacity = String(clamp(clockOp,0,1));
1024	
1025	    var lineOp = clamp((state.actTime-LINE_FADE_START)/LINE_FADE_MS,0,1);
1026	    if(state.actTime > LINE_HOLD_UNTIL) lineOp -= clamp((state.actTime-LINE_HOLD_UNTIL)/900,0,1);
1027	    lineOp = clamp(lineOp,0,1);
1028	    if(lineOp > 0.01){
1029	      elNarrative.classList.add("show");
1030	      elNarrativeLine.textContent = REQUIRED_LINE;
1031	      elNarrativeSub.textContent = "";
1032	      elNarrative.style.opacity = String(lineOp);
1033	    } else {
