   DOM overlay sync (text, opacity, control visibility) — pure fn of state
--------------------------------------------------------------------- */
function syncDOM(){
  // titlecard
  var tcOp = clamp(1 - Math.abs(state.act===1 ? (state.actTime-2600)/2600 : 2), 0, 1);
  if(state.act === 1 && state.actTime < 5200){
    elTitlecard.style.opacity = String(clamp(state.actTime<1300 ? state.actTime/1300 : (5200-state.actTime)/1600,0,1));
  } else {
    elTitlecard.style.opacity = "0";
  }

  if(state.act === 1){
    var clockOp = clamp((state.actTime-CLOCK_FADE_START)/CLOCK_FADE_MS,0,1) - (state.actTime>ACT1_FADEOUT_START?clamp((state.actTime-ACT1_FADEOUT_START)/1200,0,1):0);
    elClock.style.opacity = String(clamp(clockOp,0,1));

    var lineOp = clamp((state.actTime-LINE_FADE_START)/LINE_FADE_MS,0,1);
    if(state.actTime > LINE_HOLD_UNTIL) lineOp -= clamp((state.actTime-LINE_HOLD_UNTIL)/900,0,1);
    lineOp = clamp(lineOp,0,1);
    if(lineOp > 0.01){
      elNarrative.classList.add("show");
      elNarrativeLine.textContent = REQUIRED_LINE;
      elNarrativeSub.textContent = "";
      elNarrative.style.opacity = String(lineOp);
    } else {
      elNarrative.classList.remove("show");
    }
    elMessage.style.opacity = "0";
    elControls2.classList.remove("show");
    elControls3.classList.remove("show");
    elEpi1.style.opacity="0"; elEpi2.style.opacity="0";
    elLbTop.style.height = "6vh"; elLbBot.style.height = "6vh";
  }
  else if(state.act === 2){
    elClock.style.opacity = "0";
    elNarrative.classList.remove("show");
    elControls3.classList.remove("show");
    elEpi1.style.opacity="0"; elEpi2.style.opacity="0";
    elLbTop.style.height = "9vh"; elLbBot.style.height = "9vh";

    if(state.act2Phase === "align"){
      elControls2.classList.add("show");
      elMessage.style.opacity = "0";
      if(state.act2PhaseTime < 3400){
        elNarrative.classList.add("show");
        elNarrativeLine.textContent = "";
        elNarrativeSub.textContent = "Align the signal";
        elNarrative.style.opacity = String(clamp(state.act2PhaseTime<800?state.act2PhaseTime/800:(3400-state.act2PhaseTime)/1200,0,1));
      }
    } else {
      elControls2.classList.remove("show");
      if(state.act2Phase === "reveal"){
        var typeChars = Math.floor(REQUIRED_MESSAGE.length * clamp(state.act2PhaseTime/TYPE_MS,0,1));
        elMessage.textContent = REQUIRED_MESSAGE.slice(0, typeChars);
        elMessage.style.opacity = String(clamp(state.act2PhaseTime/250,0,1));
      } else {
        elMessage.style.opacity = "0";
      }
    }
  }
  else if(state.act === 3){
    elClock.style.opacity = "0";
    elNarrative.classList.remove("show");
    elMessage.style.opacity = String(clamp(1-(state.actTime/1200),0,1));
    if(state.actTime > 300){
      elControls3.classList.add("show");
      if(document.activeElement !== elBtnAnswer && document.activeElement !== elBtnSilent && state.actTime < 1600){
        try{ elBtnAnswer.focus({preventScroll:true}); } catch(e){ elBtnAnswer.focus(); }
      }
    }
    elLbTop.style.height = "11vh"; elLbBot.style.height = "11vh";
    elEpi1.style.opacity="0"; elEpi2.style.opacity="0";
    elReplayHint.style.opacity = "0";
  }
  else if(state.act === 4){
    elClock.style.opacity = "0";
    elNarrative.classList.remove("show");
    elControls3.classList.remove("show");
    elMessage.style.opacity = "0";
    elControls2.classList.remove("show");
    var isAnswer = state.selectedEnding === "answer";
    elLbTop.style.height = isAnswer ? "5vh" : "9vh";
    elLbBot.style.height = isAnswer ? "5vh" : "9vh";

    var epi = EPILOGUE[state.selectedEnding] || EPILOGUE.answer;
    var e1 = clamp((state.actTime-EPILOGUE_LINE1_AT)/1400,0,1);
    var e2 = clamp((state.actTime-EPILOGUE_LINE2_AT)/1400,0,1);
    elEpi1.textContent = epi[0]; elEpi1.style.opacity = String(e1);
    elEpi2.textContent = epi[1]; elEpi2.style.opacity = String(e2);

    elReplayHint.style.opacity = String(clamp((state.actTime-REPLAY_HINT_AT)/1600,0,1)*0.85);

